import{_ as a,o as t,c as d,a3 as i}from"./chunks/framework.enEKIwRN.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),o={name:"explanation/concepts.md"};function r(s,e,n,c,l,p){return t(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The domain vocabulary, each term defined once. Field-level contracts live in <a href="./../reference/">Reference</a>.</p><h2 id="desired-recorded-live" tabindex="-1">Desired / recorded / live <a class="header-anchor" href="#desired-recorded-live" aria-label="Permalink to &quot;Desired / recorded / live&quot;">​</a></h2><p>The three states reconciliation diffs: <strong>desired</strong> is your YAML; <strong>recorded</strong> is <code>.cicada/state.yaml</code> (last reconciled state + apply journal); <strong>live</strong> is what the provider actually has. Plan = desired vs recorded + recorded vs live; drift = recorded ≠ live. See <a href="./plan-apply-drift.html">Plan, apply and drift</a>.</p><h2 id="stable-local-id" tabindex="-1">Stable local id <a class="header-anchor" href="#stable-local-id" aria-label="Permalink to &quot;Stable local id&quot;">​</a></h2><p><code>id: standup</code> in YAML — the anchor mapping declared events to remote ids via recorded state and provider-side tags (<code>cicada:id</code>, <code>cicada:managed</code>, <code>cicada:state</code>). Without it, re-runs can only duplicate.</p><h2 id="managed-boundary" tabindex="-1">Managed boundary <a class="header-anchor" href="#managed-boundary" aria-label="Permalink to &quot;Managed boundary&quot;">​</a></h2><p>Exactly the recorded set: cicada only ever modifies/deletes events it applied. Live events unknown to recorded state are untouchable — a colleague&#39;s lunch on a managed calendar is safe.</p><h2 id="manifest" tabindex="-1">Manifest <a class="header-anchor" href="#manifest" aria-label="Permalink to &quot;Manifest&quot;">​</a></h2><p><code>cicada.yaml</code> — lists the calendar YAML files cicada reconciles. <code>cicada init</code> scaffolds it with <code>calendars/work.yaml</code> bound to the <code>fake</code> demo provider.</p><h2 id="provider-capabilities" tabindex="-1">Provider / capabilities <a class="header-anchor" href="#provider-capabilities" aria-label="Permalink to &quot;Provider / capabilities&quot;">​</a></h2><p>A <code>CalendarProvider</code> adapter (<code>fake</code> file-backed demo, <code>google</code> Calendar API v3) plus first-class <code>ProviderCapabilities</code> — attendee limits, reminder kinds, conferencing, tagging, conditional writes — consulted at plan time so unsupported desired states reject or warn instead of silently dropping fields.</p><h2 id="plandigest" tabindex="-1">planDigest <a class="header-anchor" href="#plandigest" aria-label="Permalink to &quot;planDigest&quot;">​</a></h2><p>The preview→apply gate, engine-side: <code>plan</code> issues a digest persisted beside the state file; <code>apply --plan-digest</code> must name an issued, unspent digest whose re-plan still matches. Single-use; a stale plan refuses. This replaced cicada-mcp&#39;s session-bound digest when T-019 deleted that binary.</p><h2 id="the-surfaces" tabindex="-1">The surfaces <a class="header-anchor" href="#the-surfaces" aria-label="Permalink to &quot;The surfaces&quot;">​</a></h2><ul><li><code>cicada</code> — the tamias <code>bins[]</code> shim → <code>tamias-driver-cicada cli</code> → engine argv (init/validate/list/plan/apply/refresh/drift/ range/show/fmt/provider).</li><li><code>cli.&lt;verb&gt;</code> ops + <code>run</code> — the pavo engine-ops wire.</li><li><code>mcp</code> — the ops manifest rendered as MCP tools (verbs as tool names). <code>provider.add</code> stays an interactive surface — OAuth needs stdin/browser, so it never becomes an op or tool.</li></ul><h2 id="single-write-path" tabindex="-1">Single write path <a class="header-anchor" href="#single-write-path" aria-label="Permalink to &quot;Single write path&quot;">​</a></h2><p>There is no <code>events.create</code> anywhere: mutations flow only through declared YAML → plan → apply. Two write paths would create unmanaged events that immediately surface as drift.</p>',18)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
